FUNCTION FIFO_CopyBytes : BOOL
VAR_INPUT
    dest : POINTER TO BYTE;
    src : POINTER TO BYTE;
    size : UDINT;
END_VAR
VAR
    i : UDINT;
    pD : POINTER TO BYTE;
    pS : POINTER TO BYTE;
END_VAR

supporting_objects.implementation:
FIFO_CopyBytes := FALSE;
IF size > 0 THEN
    pD := dest;
    pS := src;
    FOR i := 0 TO size - 1 DO
        pD^ := pS^;
        pD := pD + 1;
        pS := pS + 1;
    END_FOR;
END_IF;
FIFO_CopyBytes := TRUE;

